 // Load loads configuration from environment variables and config files
 func Load() (*Config, error) {
 	return LoadWithDefaults()
 }

 // LoadWithDefaults loads configuration with default values
 func LoadWithDefaults() (*Config, error) {
 	// Load .env file if it exists (for API keys and other environment variables)
 	// Try multiple locations: current directory, parent directory
 	envPaths := []string{".env", "../.env"}
 	for _, envPath := range envPaths {
 		if err := gotenv.Load(envPath); err == nil {
 			break // Successfully loaded .env file
 		}
 		// Continue trying other paths if this one fails
 	}

 	// Set default values
 	setDefaults()

 	// Respect an explicitly requested config file first. This is how the wrapper
 	// forces the backend to use development/testnet configs instead of falling
 	// back to the production search path.
 	if explicitConfig := os.Getenv("KNIRV_CONFIG_FILE"); explicitConfig != "" {
 		viper.SetConfigFile(explicitConfig)
 	} else {
 		// Set configuration file name and paths
 		viper.SetConfigName("production")
 		viper.SetConfigType("yaml")
 		viper.AddConfigPath("./config")
 		viper.AddConfigPath(".")

 		// Also check the canonical extracted config directory (~/.config/knirv-server/config).
 		if configDir, err := GetConfigDir(); err == nil {
 			viper.AddConfigPath(filepath.Join(configDir, "config"))
 		}
 	}

 	// Environment variable support — replace dots with underscores so that
 	// nested keys like "gateway.binary_path" map to KNIRV_GATEWAY_BINARY_PATH.
 	viper.SetEnvPrefix("KNIRV")
 	viper.SetEnvKeyReplacer(strings.NewReplacer(".", "_"))
 	viper.AutomaticEnv()
 	_ = viper.BindEnv("api.socket_path", "KNIRV_API_SOCKET", "KNIRV_API_SOCKET_PATH")

 	// Read configuration file (optional)
 	if err := viper.ReadInConfig(); err != nil {
 		if _, ok := err.(viper.ConfigFileNotFoundError); !ok {
 			return nil, fmt.Errorf("failed to read config file: %w", err)
 		}
 		// Config file not found, continue with environment variables and defaults
 	}

 	var config Config
 	if err := viper.Unmarshal(&config); err != nil {
 		return nil, fmt.Errorf("failed to unmarshal config: %w", err)
 	}

 	// Expand all paths in configuration
 	if err := config.ExpandPaths(); err != nil {
 		return nil, fmt.Errorf("failed to expand paths: %w", err)
 	}

 	// Validate configuration
 	if err := validateConfig(&config); err != nil {
 		return nil, fmt.Errorf("invalid configuration: %w", err)
 	}

 	return &config, nil
 }

 // getAppDataDir returns the XDG Base Directory for app data
 // Following XDG Base Directory Specification: ~/.local/share/knirvserver/backend_server
 func getAppDataDir() (string, error) {
 	usr, err := user.Current()
 	if err != nil {
 		return "", fmt.Errorf("failed to get current user: %v", err)
 	}

 	appDataDir := filepath.Join(usr.HomeDir, ".local", "share", "knirvserver", "backend_server")
 	if err := os.MkdirAll(appDataDir, 0755); err != nil {
 		return "", fmt.Errorf("failed to create app data directory %s: %v", appDataDir, err)
 	}

 	return appDataDir, nil
 }

 // expandPath expands paths with ~ to the user's home directory and creates them if needed
 // Relative paths are resolved relative to the application data directory, NOT the current working directory
 func expandPath(path string) (string, error) {
 	if strings.HasPrefix(path, "~") {
 		usr, err := user.Current()
 		if err != nil {
 			return "", err
 		}
 		var expanded string
 		if len(path) > 1 && (path[1] == '/' || path[1] == '\\') {
 			expanded = filepath.Join(usr.HomeDir, path[2:])
 		} else {
 			expanded = filepath.Join(usr.HomeDir, path[1:])
 		}
 		return expanded, nil
 	}

 	// Resolve relative paths relative to the application data directory (XDG Base)
 	if !filepath.IsAbs(path) {
 		appDataDir, err := getAppDataDir()
 		if err != nil {
 			// Fallback to CWD absolute path only if we can't get app data directory
 			absPath, errAbs := filepath.Abs(path)
 			if errAbs != nil {
 				return path, nil
 			}
 			return absPath, nil
 		}
 		return filepath.Join(appDataDir, path), nil
 	}

 	return path, nil
 }

 // ExpandPaths expands all paths in the configuration
 func (c *Config) ExpandPaths() error {
 	var err error

 	// Expand database path
 	if c.Database.Path != "" {
 		c.Database.Path, err = expandPath(c.Database.Path)
 		if err != nil {
 			return err
 		}
 		// Ensure directory exists
 		dbDir := filepath.Dir(c.Database.Path)
 		if err := os.MkdirAll(dbDir, 0755); err != nil {
 			return fmt.Errorf("failed to create database directory: %v", err)
 		}
 	}

 	// Expand CDE paths
 	if c.CDE.BaseImagePath != "" {
 		c.CDE.BaseImagePath, err = expandPath(c.CDE.BaseImagePath)
 		if err != nil {
 			return err
 		}
 		if err := os.MkdirAll(c.CDE.BaseImagePath, 0755); err != nil {
 			return fmt.Errorf("failed to create base image directory: %v", err)
 		}
 	}

 	if c.CDE.WorkspaceRoot != "" {
 		c.CDE.WorkspaceRoot, err = expandPath(c.CDE.WorkspaceRoot)
 		if err != nil {
 			return err
 		}
 		if err := os.MkdirAll(c.CDE.WorkspaceRoot, 0755); err != nil {
 			return fmt.Errorf("failed to create workspace root directory: %v", err)
 		}
 	}

 	if c.CDE.ProjectStoragePath != "" {
 		c.CDE.ProjectStoragePath, err = expandPath(c.CDE.ProjectStoragePath)
 		if err != nil {
 			return err
 		}
 		if err := os.MkdirAll(c.CDE.ProjectStoragePath, 0755); err != nil {
 			return fmt.Errorf("failed to create project storage directory: %v", err)
 		}
 	}

 	// Expand reports path
 	if c.Reports.StoragePath != "" {
 		c.Reports.StoragePath, err = expandPath(c.Reports.StoragePath)
 		if err != nil {
 			return err
 		}
 		if err := os.MkdirAll(c.Reports.StoragePath, 0755); err != nil {
 			return fmt.Errorf("failed to create reports directory: %v", err)
 		}
 	}

 	// Expand log output path — only create the directory when the path is absolute
 	// to avoid creating spurious directories relative to CWD.
 	if c.Log.Output != "" {
 		c.Log.Output, err = expandPath(c.Log.Output)
 		if err != nil {
 			return err
 		}
 		if filepath.IsAbs(c.Log.Output) {
 			logDir := filepath.Dir(c.Log.Output)
 			if err := os.MkdirAll(logDir, 0755); err != nil {
 				return fmt.Errorf("failed to create logs directory: %v", err)
 			}
 		}
 	}

 	// Expand model server storage path
 	if c.ModelServer.StoragePath != "" {
 		c.ModelServer.StoragePath, err = expandPath(c.ModelServer.StoragePath)
 		if err != nil {
 			return err
 		}
 		if err := os.MkdirAll(c.ModelServer.StoragePath, 0755); err != nil {
 			return fmt.Errorf("failed to create model server storage directory: %v", err)
 		}
 	}

+	// Expand Graph paths (DataPath, SocketPath, P2PSocketPath, BinaryPath)
+	if c.Graph.DataPath != "" {
+		c.Graph.DataPath, err = expandPath(c.Graph.DataPath)
+		if err != nil {
+			return err
+		}
+		if err := os.MkdirAll(c.Graph.DataPath, 0755); err != nil {
+			return fmt.Errorf("failed to create graph data directory: %v", err)
+		}
+	}
+	if c.Graph.SocketPath != "" {
+		c.Graph.SocketPath, err = expandPath(c.Graph.SocketPath)
+		if err != nil {
+			return err
+		}
+		if err := os.MkdirAll(filepath.Dir(c.Graph.SocketPath), 0755); err != nil {
+			return fmt.Errorf("failed to create graph socket directory: %v", err)
+		}
+	}
+	if c.Graph.P2PSocketPath != "" {
+		c.Graph.P2PSocketPath, err = expandPath(c.Graph.P2PSocketPath)
+		if err != nil {
+			return err
+		}
+		if err := os.MkdirAll(filepath.Dir(c.Graph.P2PSocketPath), 0755); err != nil {
+			return fmt.Errorf("failed to create graph p2p socket directory: %v", err)
+		}
+	}
+	if c.Graph.BinaryPath != "" {
+		c.Graph.BinaryPath, err = expandPath(c.Graph.BinaryPath)
+		if err != nil {
+			return err
+		}
+	}
+
+	// Expand Chain paths (same issue as Graph - tilde not expanded)
+	if c.Chain.DataPath != "" {
+		c.Chain.DataPath, err = expandPath(c.Chain.DataPath)
+		if err != nil {
+			return err
+		}
+		if err := os.MkdirAll(c.Chain.DataPath, 0755); err != nil {
+			return fmt.Errorf("failed to create chain data directory: %v", err)
+		}
+	}
+	if c.Chain.SocketPath != "" {
+		c.Chain.SocketPath, err = expandPath(c.Chain.SocketPath)
+		if err != nil {
+			return err
+		}
+		if err := os.MkdirAll(filepath.Dir(c.Chain.SocketPath), 0755); err != nil {
+			return fmt.Errorf("failed to create chain socket directory: %v", err)
+		}
+	}
+	if c.Chain.P2PSocketPath != "" {
+		c.Chain.P2PSocketPath, err = expandPath(c.Chain.P2PSocketPath)
+		if err != nil {
+			return err
+		}
+		if err := os.MkdirAll(filepath.Dir(c.Chain.P2PSocketPath), 0755); err != nil {
+			return fmt.Errorf("failed to create chain p2p socket directory: %v", err)
+		}
+	}
+	if c.Chain.BinaryPath != "" {
+		c.Chain.BinaryPath, err = expandPath(c.Chain.BinaryPath)
+		if err != nil {
+			return err
+		}
+	}
+
 	return nil
